package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type AmtRec struct {
	ArAcct string
	ArAmt  decimal.Decimal
}

var WsEofFlag string = "N"
var WsBigTotal decimal.Decimal = decimal.NewFromInt(0)
var WsWrapTotal decimal.Decimal = decimal.NewFromInt(0)
var WsSafeTotal decimal.Decimal = decimal.NewFromInt(0)
var WsOverflows int64 = 0
var WsCount int64 = 0
var WsHalf decimal.Decimal = decimal.NewFromInt(0)
var WsAmtEd string
var WsWrapEd string
var WsSafeEd string
var WsHalfEd string

var amtRec AmtRec
var amtLines []string
var amtIdx int

func main() {
	// OPEN INPUT AMT-FILE
	f, err := os.Open("input.dat")
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	scanner := bufio.NewScanner(f)
	for scanner.Scan() {
		line := scanner.Text()
		amtLines = append(amtLines, line)
	}
	f.Close()

	MAIN_PARA()

}

func MAIN_PARA() {
	PERFORM_READ_PARA()
	for !INPUT_DONE() {
		PROCESS_PARA()
	}
	CLOSE_AMT_FILE()
	SUMMARY_PARA()
}

func CLOSE_AMT_FILE() {}

func INPUT_DONE() bool { return WsEofFlag == "Y" }

func PERFORM_READ_PARA() { READ_PARA() }

func READ_PARA() {
	if amtIdx >= len(amtLines) {
		WsEofFlag = "Y"
		return
	}
	line := amtLines[amtIdx]
	amtIdx++
	// pad with spaces on right to record length 11
	if len(line) < 11 {
		line = line + strings.Repeat(" ", 11-len(line))
	}
	if len(line) > 11 {
		line = line[:11]
	}
	amtRec.ArAcct = line[0:4]
	s := line[4:11]
	// s contains digits only
	// PIC 9(5)V99 -> 5+2=7 digits, implied 2 decimals
	s = strings.TrimSpace(s)
	if s == "" {
		s = "0"
	}
	// Remove any non-digit (should be digits)
	// parse
	n := int64(0)
	for _, ch := range s {
		if ch >= '0' && ch <= '9' {
			n = n*10 + int64(ch-'0')
		}
	}
	// If s had leading zeros, above works. Equivalent to decimal.New(n, -2)
	amtRec.ArAmt = decimal.New(n, -2)
}

func PROCESS_PARA() {
	// ADD AR-AMT TO WS-BIG-TOTAL
	WsBigTotal = WsBigTotal.Add(amtRec.ArAmt)
	WsBigTotal = truncToScale(WsBigTotal, 2)
	WsBigTotal = wrapHighDigits(WsBigTotal, 7, 2)

	// MOVE WS-BIG-TOTAL TO WS-WRAP-TOTAL (wrap high digits)
	WsWrapTotal = wrapHighDigits(WsBigTotal, 5, 2)

	// ADD AR-AMT TO WS-SAFE-TOTAL ON SIZE ERROR PERFORM OVERFLOW-PARA
	tentative := WsSafeTotal.Add(amtRec.ArAmt)
	tentative = truncToScale(tentative, 2)
	if isOverflow(tentative, 5, 2) {
		OVERFLOW_PARA()
	} else {
		WsSafeTotal = tentative
	}

	// ADD 1 TO WS-COUNT
	WsCount = WsCount + 1
	// keep low-order digits for PIC 99 (2 digits) – wrap 100
	// spec says storing keeps low-order digits
	WsCount = WsCount % 100

	// COMPUTE WS-HALF = AR-AMT / 2  (no ROUNDED => truncated)
	// use decimal division
	half := amtRec.ArAmt.Div(decimal.NewFromInt(2))
	half = half.Truncate(1)
	// store into PIC 9(5)V9 -> wrap high digits
	WsHalf = wrapHighDigits(half, 5, 1)

	// MOVE AR-AMT TO WS-AMT-ED  PIC ZZ,ZZ9.99
	WsAmtEd = formatEdited(amtRec.ArAmt, "ZZ,ZZ9.99")
	// MOVE WS-WRAP-TOTAL TO WS-WRAP-ED
	WsWrapEd = formatEdited(WsWrapTotal, "ZZ,ZZ9.99")
	// MOVE WS-SAFE-TOTAL TO WS-SAFE-ED
	WsSafeEd = formatEdited(WsSafeTotal, "ZZ,ZZ9.99")
	// MOVE WS-HALF TO WS-HALF-ED  PIC ZZ,ZZ9.9
	WsHalfEd = formatEdited(WsHalf, "ZZ,ZZ9.9")

	// DISPLAY
	// DISPLAY AR-ACCT " " WS-AMT-ED " " WS-WRAP-ED " " WS-SAFE-ED " " WS-HALF-ED
	fmt.Printf("%s %s %s %s %s\n", amtRec.ArAcct, WsAmtEd, WsWrapEd, WsSafeEd, WsHalfEd)

	PERFORM_READ_PARA()
}

func SUMMARY_PARA() {
	// DISPLAY "RECORDS: " WS-COUNT  (unedited numeric PIC 99 zero-padded width 2)
	fmt.Printf("RECORDS: %s\n", formatUnedited(WsCount, 2))
	fmt.Printf("OVERFLOWS: %s\n", formatUnedited(WsOverflows, 2))
}

func OVERFLOW_PARA() {
	WsOverflows = WsOverflows + 1
	WsOverflows = WsOverflows % 100
}

// helpers

func truncToScale(d decimal.Decimal, scale int32) decimal.Decimal {
	return d.Truncate(scale)
}

func isOverflow(d decimal.Decimal, intDigits int, scale int32) bool {
	// overflow if absolute value >= 10^intDigits
	// max = 10^intDigits - 10^-scale  but check integer part digits
	// simpler: check if integer part >= 10^intDigits
	// for non-negative values: d >= 10^intDigits
	limit := decimal.New(1, int32(intDigits)) // 10^intDigits
	if d.Cmp(limit) >= 0 {
		return true
	}
	if d.Sign() < 0 {
		// negative overflow if < -limit
		negLimit := limit.Neg()
		if d.Cmp(negLimit) < 0 {
			return true
		}
	}
	return false
}

func wrapHighDigits(d decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	// keep low-order digits that fit: modulo 10^(intDigits+scale) on scaled integer
	// d is already truncated to scale
	// work with scaled integer = d * 10^scale  (shift)
	scaled := d.Shift(scale) // d * 10^scale
	// modulus = 10^(intDigits+scale)
	mod := decimal.New(1, int32(intDigits+scale))
	// for non-negative, mod operation
	// for generality handle negative by mod keeping sign? COBOL drophigh keeps sign?
	// values are non-negative here
	if d.Sign() < 0 {
		// keep sign, wrap absolute
		absScaled := scaled.Abs()
		rem := absScaled.Mod(mod)
		rem = rem.Neg()
		return rem.Shift(-scale)
	}
	rem := scaled.Mod(mod)
	return rem.Shift(-scale)
}

func formatUnedited(v int64, width int) string {
	// zero-padded
	s := fmt.Sprintf("%d", v)
	if len(s) > width {
		// keep low-order digits (high-order dropped)
		s = s[len(s)-width:]
	} else if len(s) < width {
		s = strings.Repeat("0", width-len(s)) + s
	}
	return s
}

func formatEdited(d decimal.Decimal, pic string) string {
	// derive integerSlots and decimalSlots from pic
	// pic like "ZZ,ZZ9.99" or "ZZ,ZZ9.9"
	dot := strings.Index(pic, ".")
	var intPat, decPat string
	if dot >= 0 {
		intPat = pic[:dot]
		decPat = pic[dot+1:]
	} else {
		intPat = pic
		decPat = ""
	}
	intSlots := 0
	for _, ch := range intPat {
		if ch == 'Z' || ch == '9' {
			intSlots++
		}
	}
	decSlots := 0
	for _, ch := range decPat {
		if ch == 'Z' || ch == '9' {
			decSlots++
		}
	}
	// integer part handling: drop high-order digits
	// get truncated to decSlots (d already at correct scale, but ensure)
	// For safety truncate
	d = d.Truncate(int32(decSlots))
	// get integer part absolute
	signNeg := d.Sign() < 0
	if signNeg {
		d = d.Abs()
	}
	// integer part and decimal part strings
	// decimal.Shift(decSlots) gives integer scaled
	scaled := d.Shift(int32(decSlots))
	// scaled int string
	scaledInt := scaled.Truncate(0)
	// we need decimal digits
	scaleStr := scaledInt.String()
	// scaleStr may contain decimal exponent? decimal.String gives plain
	// remove minus
	// pad leading zeros to decSlots+1 at least
	// We need to split integer and decimal: integer = floor(d), decimal = fraction
	// Use string manipulation via Format with fixed?
	// Easier: get integer part and fractional part via DivMod?
	// Use scaled integer string padded
	needLen := decSlots + 1 // at least one integer digit
	if len(scaleStr) < needLen {
		scaleStr = strings.Repeat("0", needLen-len(scaleStr)) + scaleStr
	}
	intStr := scaleStr[:len(scaleStr)-decSlots]
	if intStr == "" {
		intStr = "0"
	}
	decStr := ""
	if decSlots > 0 {
		decStr = scaleStr[len(scaleStr)-decSlots:]
	}
	// Now high-order truncation for integer part: keep low-order intSlots digits
	if len(intStr) > intSlots {
		intStr = intStr[len(intStr)-intSlots:]
	}
	// Pad intStr to intSlots with leading zeros
	if len(intStr) < intSlots {
		intStr = strings.Repeat("0", intSlots-len(intStr)) + intStr
	}
	// Now need picture types for integer slots
	types := []rune{}
	for _, ch := range intPat {
		if ch == 'Z' || ch == '9' {
			types = append(types, ch)
		}
	}
	// Determine suppression for integer slots
	// first non-zero index
	firstNonZero := -1
	for i, ch := range intStr {
		if ch != '0' {
			firstNonZero = i
			break
		}
	}
	// suppressed array
	suppressed := make([]bool, intSlots)
	if firstNonZero == -1 {
		// all zero
		for i := 0; i < intSlots; i++ {
			if types[i] == 'Z' {
				suppressed[i] = true
			} else {
				suppressed[i] = false
			}
		}
	} else {
		for i := 0; i < intSlots; i++ {
			if i < firstNonZero && types[i] == 'Z' {
				suppressed[i] = true
			} else {
				suppressed[i] = false
			}
		}
	}
	// Build integer section with commas
	// Iterate over intPat characters, consuming digit index
	var outInt strings.Builder
	digitIdx := 0
	// Need to know for each comma if there is a non-suppressed digit to its left
	// We can decide per comma after building suppression: comma is shown if any non-suppressed digit exists left of it
	// Track if any non-suppressed seen so far among digits
	seenNonSuppressed := false
	// Precompute for each position in intPat whether comma should be shown
	// We can process left to right
	for _, ch := range intPat {
		if ch == ',' {
			if seenNonSuppressed {
				outInt.WriteRune(',')
			} else {
				outInt.WriteRune(' ')
			}
		} else if ch == 'Z' || ch == '9' {
			if suppressed[digitIdx] {
				outInt.WriteRune(' ')
			} else {
				outInt.WriteRune(rune(intStr[digitIdx]))
			}
			if !suppressed[digitIdx] {
				seenNonSuppressed = true
			}
			digitIdx++
		}
	}
	intFormatted := outInt.String()
	decFormatted := ""
	if decSlots > 0 {
		decFormatted = "." + decStr
	}
	result := intFormatted + decFormatted
	// result length should equal pic length (including dot and commas)
	// pic length includes dot
	expectedLen := len(pic)
	if len(result) < expectedLen {
		// pad left? Should not happen because intFormatted already correct width
		result = strings.Repeat(" ", expectedLen-len(result)) + result
	}
	// sign handling not needed (positive)
	if signNeg {
		// COBOL would show minus? Not needed
	}
	return result
}

